xml.Script:
        Colors[0] := 'EE0000'; // Red
        Colors[1] := '009900'; // Green
        Colors[2] := 'FFFFFF'; // White
        Colors[3] := 'FF7700'; // Orange
        Colors[4] := '0077FF'; // LightBlue
        Colors[5] := 'FFEE00'; // Yellow
        Colors[6] := '0033EE'; // Blue
        Colors[7] := 'CC00DD'; // Rose

        R := 0.5;
        H := R * 0.6;
        D := R * 0.6;

        N := 40;
        for i := 0 to N - 1 do begin
            x[i] := R * cos(2 * Pi / N * i);
            y[i] := R * sin(2 * Pi / N * i);
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

Macro.Script:
i1 := i mod N;
i2 := (i + 1) mod N;
Inc(i);
